/// No test in this crate can spawn a TypeScript runtime.
///
/// Trace: FR-101-AC-5
/// Provenance: quoin#476
#[test]
fn tc_476_022_no_test_runs_the_retained_typescript() {
    let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests");
    let mut checked = 0_usize;
    for entry in std::fs::read_dir(&root).expect("tests/ is readable") {
        let path = entry.expect("a directory entry").path();
        // This census names the forbidden spellings in order to forbid them.
        let is_this_file = path
            .file_name()
            .is_some_and(|name| name == "tc_476_boundary.rs");
        if path.extension().is_some_and(|extension| extension == "rs") && !is_this_file {
            let code = code_of(&std::fs::read_to_string(&path).expect("a test file"));
            checked += 1;
            for forbidden in ["std::process::Command", "ts-node", "node --"] {
                assert!(
                    !code.contains(forbidden),
                    "{}: contains {forbidden}; the oracle is a committed golden, \
                     captured once (FR-101-AC-5)",
                    path.display()
                );
            }
        }
    }
    assert!(
        checked >= 4,
        "anti-vacuity floor: at least 4 test files expected, saw {checked}"
    );
}

/// Every sealed record reproduces its own digest, and its filename is that
/// digest.
///
/// Trace: FR-098-CON-1
#[test]
fn tc_380_every_sealed_record_verifies_and_is_named_by_its_digest() {
    let records = files_under(
        &fixture_root().join("spec/evidence/change-assurance/records"),
        ".json",
    );
    assert_eq!(records.len(), 3, "the fixture must not lose records");
    for path in records {
        let bytes = std::fs::read(&path).expect("read");
        let value = parse_strict_json(&bytes).expect("the oracle wrote strict JSON");
        let object = value.as_object().expect("a record is an object");
        let digest = verify_record_digest(object).expect("record verifies against its own digest");
        let stem = path
            .file_stem()
            .expect("stem")
            .to_string_lossy()
            .into_owned();
        assert_eq!(
            stem,
            digest.as_hex(),
            "{}: filename is the digest",
            path.display()
        );
        assert_eq!(
            CanonicalDigest::parse_stored(&stem).expect("parses"),
            digest
        );
    }
}

/// Trace: FR-102-AC-6
/// Provenance: quoin#373, quoin#521
#[test]
fn tc_1654_the_native_binary_has_no_oclif_or_typescript_shell() {
    let root = repository_root();
    for retired in [
        "bin/quoin.js",
        "cli-agent-evals.config.mjs",
        "evals",
        "rust/crates/quoin-schemas",
        "src/base.ts",
        "src/cli.ts",
        "src/commands",
        "src/core",
        "src/flow-command.ts",
        "src/hooks",
        "scripts",
        "smoke",
        "vite.config.ts",
    ] {
        assert!(
            !root.join(retired).exists(),
            "the retired Node/oclif shell path remains: {retired}"
        );
    }

    // `package.json` and `pnpm-lock.yaml` are no longer on the retired list
    // (PLAT-157): the repository root carries one, declaring the single
    // `@agent-ix/ix-spec-workflows` dependency quoin-cli's `flow` module
    // resolves at run time, which is unrelated to the retired CLI shell. What
    // actually identified that shell was `oclif` and a `bin` entry pointing at
    // `bin/quoin.js` -- assert those two markers are absent instead of
    // banning the manifest outright.
    if let Ok(package_json) = std::fs::read_to_string(root.join("package.json")) {
        let manifest: serde_json::Value =
            serde_json::from_str(&package_json).expect("package.json is valid JSON");
        assert!(
            manifest.get("oclif").is_none(),
            "an `oclif` key in package.json means the retired CLI shell is back"
        );
        assert!(
            manifest.get("bin").is_none(),
            "a `bin` key in package.json means the retired CLI shell is back"
        );
    }

    let mut sources = Vec::new();
    for directory in ["src", "tests"] {
        let directory = root.join(directory);
        if directory.exists() {
            node_sources(&directory, &mut sources);
        }
    }
    assert!(
        sources.is_empty(),
        "retired Node/TypeScript sources: {sources:?}"
    );

    let core = root.join("rust/crates/quoin-core");
    let core_manifest = std::fs::read_to_string(core.join("Cargo.toml"))
        .expect("the shared runtime manifest is readable");
    assert!(
        !core_manifest.contains("[[bin]]") && !core_manifest.contains("default-run"),
        "quoin-core must remain a library, not a second executable target"
    );
    assert!(
        !core.join("src/main.rs").exists(),
        "the retired quoin-core executable source remains"
    );
}

