}

/// No source in this crate typechecks or evaluates a clause: quoin records
/// clause text and its locus, and the checking is somebody else's job.
///
/// A census over every module `lib.rs` declares, not a hand-listed subset: the
/// list below is asserted to be that declaration set, so a module added to the
/// crate and not to this guard fails here rather than escaping it.
///
/// Trace: FR-072-CON-1
/// Provenance: agent-ix/quoin#452
#[test]
fn tc_452_653_no_source_in_the_crate_typechecks_or_evaluates_a_clause() {
    const LIB: &str = include_str!("../src/lib.rs");
    const SOURCES: [(&str, &str); 10] = [
        ("contract", include_str!("../src/contract.rs")),
        ("data_schema", include_str!("../src/data_schema.rs")),
        ("diagnostic", include_str!("../src/diagnostic.rs")),
        ("embedded", include_str!("../src/embedded.rs")),
        ("error", include_str!("../src/error.rs")),
        ("ids", include_str!("../src/ids.rs")),
        ("manifest", include_str!("../src/manifest.rs")),
        (
            "package_manifest",
            include_str!("../src/package_manifest.rs"),
        ),
        ("schema", include_str!("../src/schema.rs")),
        ("sweep", include_str!("../src/sweep.rs")),
    ];

    let declared: Vec<&str> = LIB
        .lines()
        .filter_map(|line| line.trim().strip_prefix("pub mod "))
        .filter_map(|rest| rest.strip_suffix(';'))
        .collect();
    assert!(!declared.is_empty(), "lib.rs declares no modules");
    let scanned: Vec<&str> = SOURCES.iter().map(|(name, _)| *name).collect();
    assert_eq!(
        declared, scanned,
        "every module the crate declares must be scanned"
    );

    for (name, source) in SOURCES {
        for forbidden in ["typecheck", "type_check", "eval_clause", "ocl_parse"] {
            assert!(!source.contains(forbidden), "{name}.rs names {forbidden}");
        }
    }
}

/// Each format-specific adapter is reachable both by `--adapter` and by
/// the tool strings its producers spell.
///
/// Selection is the half of an adapter nothing else asserts: a parser that
/// works and is never selected reads, from the store, exactly like a parser
/// that does not exist.
///
/// Trace: FR-036-AC-5, FR-041-AC-6, FR-042-AC-5
/// Provenance: quoin#458
#[test]
fn tc_458_240_each_adapter_is_reachable_by_name_and_by_declared_tool() {
    let by_name = [
        ("sbom", "sbom"),
        ("agent-eval", "agent-eval"),
        ("audit-script", "audit-script"),
    ];
    for (adapter, expected) in by_name {
        let chosen = select(adapter, expected);
        assert_eq!(chosen, expected, "--adapter {adapter}");
    }
    let by_tool = [
        ("syft 1.0.0", "sbom"),
        ("cyclonedx-npm 6.0.1", "sbom"),
        ("cli-agent-evals 0.4.0", "agent-eval"),
        ("make ci", "audit-script"),
        ("import-linter 2.0", "audit-script"),
    ];
    for (tool, expected) in by_tool {
        let chosen = select_by_tool(tool, expected);
        assert_eq!(chosen, expected, "--tool {tool}");
    }
    // Anti-vacuity: the table above must name more than one adapter, or a
    // registry collapsed onto a single entry would satisfy every row.
    let distinct: BTreeSet<&str> = by_tool.iter().map(|(_, name)| *name).collect();
    assert_eq!(distinct.len(), 3);
}

/// Trace: FR-063-AC-5
///
/// Sealing produces the oracle's bytes and the oracle's digest. This is the
/// pinned RFC 8785 / BLAKE3 contract: the digest compared against is a hex
/// string `sealChangeRecord` wrote, and the bytes are the canonical bytes of
/// the record it sealed — including one input whose collections arrived
/// unsorted, so the normalization is exercised rather than assumed.
#[test]
fn tc_455_sealing_reproduces_the_oracles_bytes_and_digest() {
    let records = records();
    let mut normalized = 0_usize;
    for (name, input, sealed) in &records {
        let record = seal_change_record(input).unwrap_or_else(|error| panic!("{name}: {error}"));
        assert_eq!(
            record.digest.as_hex(),
            text(sealed, "digest"),
            "{name}: the sealed digest disagrees with the oracle's"
        );
        assert_eq!(
            record_bytes(&record).unwrap(),
            canonical_bytes(sealed).unwrap(),
            "{name}: the canonical bytes disagree with the oracle's"
        );
        if canonical_bytes(input).unwrap() != canonical_bytes(&without(sealed, "digest")).unwrap() {
            normalized += 1;
        }
    }
    assert!(
        normalized >= 1,
        "anti-vacuity floor: at least one input must differ from its sealed form, \
         or normalization is untested"
    );
}

