/// `change_assurance.receipt` records `governing_plan_id` and
/// `diff_paths_supplied` on the sealed receipt, through the operation and not
/// only through the library: a receipt sealed with `--plan`/`--diff-path`
/// records the plan id and `true`; one sealed with neither records `null` and
/// `false` explicitly, rather than a caller's omission producing the same
/// silence a genuinely unlinked record would (PLAT-1015).
///
/// Trace: FR-111-AC-5, TC-1915
/// Provenance: PLAT-1015
#[test]
fn tc_1015_614_receipt_records_governing_plan_id_and_diff_paths_supplied() {
    let fixture = case("everything-agrees");
    let root = repo();
    seal_record(root.path(), &fixture);
    intake_all(root.path(), &fixture);
    write_protecting_plan(root.path(), "MP-1015-CORE", &["checker/config.toml"]);

    let mut linked = receipt_request(root.path(), &fixture);
    linked["diff_paths"] = json!(["src/lib.rs"]);
    linked["plan"] = json!("MP-1015-CORE");
    let payload = ok(&run("change_assurance.receipt", &linked));
    assert_eq!(
        payload["receipt"]["governing_plan_id"],
        json!("MP-1015-CORE")
    );
    assert_eq!(payload["receipt"]["diff_paths_supplied"], json!(true));

    let unlinked = receipt_request(root.path(), &fixture);
    let payload = ok(&run("change_assurance.receipt", &unlinked));
    assert_eq!(payload["receipt"]["governing_plan_id"], json!(null));
    assert_eq!(payload["receipt"]["diff_paths_supplied"], json!(false));
}

/// The vendored module-manifest schema adds no required key anywhere against
/// the pre-CR-003 schema, so a manifest that validated before still validates.
///
/// The census has a floor: the pre-CR-003 baseline must itself carry required
/// arrays, or "every one of them is unchanged" is a statement about none of
/// them.
///
/// The baseline is the 14 `(path, required)` pairs `required_arrays` produced
/// over filament-core-service's `module-manifest.schema.json` at the commit
/// before CR-003 (agent-ix/filament-core-service#21) added the `semantic`
/// block — recorded here as data rather than as a second copy of the whole
/// schema document beside the current one. The commit CR-003 landed against
/// is quoin's own git history, not this working tree; the point of this
/// constant is that nothing here needs to re-read it to keep asserting the
/// constraint.
///
/// Trace: FR-070-CON-1, NFR-017-AC-4
/// Provenance: agent-ix/quoin#452
#[test]
fn tc_452_641_the_vendored_schema_adds_no_required_key_versus_pre_cr003() {
    const PRE_CR003_REQUIRED_ARRAYS: &[(&str, &[&str])] = &[
        ("", &["manifest_version", "name", "version"]),
        ("/$defs/ArchetypeEntry", &["kind"]),
        (
            "/$defs/ArtifactTypeEntry",
            &["name", "grammar_ref", "frontmatter_schema_ref"],
        ),
        ("/$defs/BodyExtraction", &["yield_pattern"]),
        (
            "/$defs/BodyExtraction/properties/emit_edges/items",
            &["type", "target"],
        ),
        (
            "/$defs/BodyExtraction/properties/yield_pattern/properties/iterate_over",
            &["section_path", "kind"],
        ),
        ("/$defs/EdgeTypeEntry", &["description", "category"]),
        ("/$defs/GrammarEntry", &["name"]),
        ("/$defs/LintRuleEntry/properties/pattern", &["kind"]),
        ("/$defs/LocatorPrimitive", &["from"]),
        ("/$defs/ObjectTypeEntry", &["name"]),
        ("/$defs/RoleEntry", &["description"]),
        ("/properties/depends_on/items", &["name", "version_range"]),
        ("/properties/nav/properties/category", &["slug", "label"]),
    ];

    let before: BTreeMap<String, Vec<String>> = PRE_CR003_REQUIRED_ARRAYS
        .iter()
        .map(|(path, required)| {
            (
                (*path).to_owned(),
                required.iter().map(|s| (*s).to_owned()).collect(),
            )
        })
        .collect();
    let mut after = BTreeMap::new();
    required_arrays(
        &read_json(&module_manifest_schema_path(&semantic_root())),
        "",
        &mut after,
    );
    assert!(
        before.len() >= 3,
        "the pre-CR-003 schema carries {} required arrays; the comparison would be vacuous",
        before.len()
    );

    for (path, required) in &before {
        assert_eq!(after.get(path), Some(required), "{path}");
    }
    for path in after.keys().filter(|path| !before.contains_key(*path)) {
        assert!(
            path.contains("/properties/semantic")
                || path.contains("/data_schema/")
                // `$defs/ConstructDeclaration` (filament-core-service#33): an optional
                // semantic-IR construct declaration a manifest may attach to an object
                // type via `ObjectTypeEntry.properties.construct`, which is itself
                // optional -- a manifest that never sets `construct` never has this
                // def's own `required` array evaluated, so it adds no obligation to a
                // manifest that validated before.
                || path.contains("/$defs/ConstructDeclaration"),
            "new required array outside the optional nodes: {path}"
        );
    }
    assert_eq!(
        after.get(""),
        Some(&vec![
            "manifest_version".to_owned(),
            "name".to_owned(),
            "version".to_owned()
        ])
    );
}

/// The type check and the read observe the file that was opened, not
/// whatever the path names afterwards. The file is opened, then the path
/// is swapped — first for a FIFO, then for a symlink to other bytes —
/// before the handle is digested; the digest is still the opened file's.
/// A digest that re-read the path (the `symlink_metadata`-then-`read`
/// shape this replaced) would see the swap and refuse, block, or digest
/// the other bytes.
///
/// Trace: FR-110-AC-10
/// Provenance: PLAT-985, quoin#600
#[cfg(unix)]
#[test]
fn tc_985_the_digest_reads_the_opened_handle_not_the_path() {
    let dir = tempdir("swap");
    let path = dir.join("answers.json");
    let other = dir.join("other.json");
    std::fs::write(&other, b"xyz").expect("write");
    let abc = "sha256:ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad";

    std::fs::write(&path, b"abc").expect("write");
    let file = open_for_digest(&path).expect("opens");
    std::fs::remove_file(&path).expect("unlink");
    make_fifo(&path);
    let digest = digest_opened_file(&file, &path).expect("digests the opened file");
    assert_eq!(digest.to_stored(), abc);

    std::fs::remove_file(&path).expect("unlink");
    std::fs::write(&path, b"abc").expect("write");
    let file = open_for_digest(&path).expect("opens");
    std::fs::remove_file(&path).expect("unlink");
    std::os::unix::fs::symlink(&other, &path).expect("symlink");
    let digest = digest_opened_file(&file, &path).expect("digests the opened file");
    assert_eq!(digest.to_stored(), abc);

    // The path as it now reads is refused, so the two answers above came
    // from the handle and not from a second look at the path.
    let error = digest_file_sha256(&path).expect_err("a link is not its target");
    assert_eq!(error.code(), StoreErrorCode::DigestSourceIsSymlink);

    std::fs::remove_dir_all(&dir).ok();
}

/// Trace: FR-018-AC-5
/// Provenance: quoin#446, carried from tests/props/fr-018.prop.test.ts
#[test]
fn tc_446_061_an_unknown_prefix_is_kept_rather_than_stripped() {
    const KNOWN: [&str; 3] = ["path", "github", "package"];
    let mut checked = 0_usize;
    for first in b'a'..=b'z' {
        for second in b'a'..=b'z' {
            let scheme = String::from_utf8(vec![first, second]).expect("ascii");
            if KNOWN.contains(&scheme.as_str()) {
                continue;
            }
            for rest in ["x", "a/b", "./rel", "/abs/path", "a-b.c"] {
                let arg = format!("{scheme}:{rest}");
                assert_eq!(path_of(&arg), arg, "{arg}");
                checked += 1;
            }
        }
    }
    // Not a check over an empty population: 676 two-letter schemes, none of
    // which is one of the three known prefixes, times five argument shapes.
    assert_eq!(checked, 26 * 26 * 5, "the enumeration did not run in full");
}

/// Real producer evidence, adapted by FR-066 and then projected by FR-067 —
/// the two halves of StR-007 joined, as the deleted test joined them.
///
/// Trace: StR-007-VC-1
/// Provenance: quoin#480
#[test]
fn tc_480_048_adapted_evidence_reaches_the_portfolio_intact() {
    let (adapted, producer_plan, declared_identity, declared_scorer) = adapted_producer_evidence();
    let snapshot = PortfolioCollectionSnapshot {
        root: PathBuf::from("/repos/a"),
        collections: vec![adapted.clone()],
    };
    let base = build_portfolio_report_from_collections(&[snapshot])
        .repositories
        .into_iter()
        .next()
        .expect("the ungoverned portfolio carries the repository");
    let path = format!(
        "/repos/a/spec/evidence/measurements/{}.json",
        adapted.collection_id.as_str()
    );
    let report = build(&[GraphPortfolioRepositoryInput {
        portfolio: base,
        plans: vec![producer_plan],
        collections: vec![GraphCollectionRead::read(path, adapted)],
        graph: no_graph(),
    }]);

    let repository = &report.repositories[0];
    let current = repository
        .graph_quality
        .current
        .as_ref()
        .expect("the adapted evidence is a current reading");
    assert_eq!(
        current.producer_record_digest.as_deref(),
        Some(declared_identity.as_str()),
        "the producer's own record identity survives both halves unchanged"
    );
    assert_eq!(
        current.scorer_digest.as_deref(),
        Some(declared_scorer.as_str()),
        "the retained scorer identity survives both halves unchanged"
    );
    assert!(
        current.partitions.len() > 1,
        "the producer's partitions are not collapsed into one"
    );
    assert_eq!(
        repository.graph.availability(),
        GapAvailability::Missing.as_str(),
        "adapted quality evidence does not conjure a structural graph"
    );
    let canonical = canonical_graph_portfolio_json(&report).expect("canonical JSON");
    for forbidden in ["aggregateScore", "qualityVerdict", "child_process"] {
        assert!(
            !canonical.contains(forbidden),
            "the projection produced `{forbidden}`"
        );
    }
    let identities: BTreeSet<(&str, &str, &str)> = current
        .partitions
        .iter()
        .map(|row| {
            (
                row.identity.measure.as_str(),
                row.identity.dimension.as_str(),
                row.identity.key.as_str(),
            )
        })
        .collect();
    assert_eq!(
        identities.len(),
        current.partitions.len(),
        "each partition keeps its own identity"
    );
}

