/// The corpus edges the caller's vocabulary selects (`analysis.ts:523`).
///
/// # "corpus" is the spec corpus
///
/// [`AssuranceRelation::Corpus`] is an edge between two documents in the spec
/// corpus — `FR-001 refines StR-002`. It has nothing to do with
/// evidence-corpus accounting, which belongs to engineering-assurance. The
/// name has already sent one reader to the wrong subsystem (quoin#385).
///
/// # Which unusable edges are reported and which are not
///
/// A selected edge that resolves both ends to artifacts the export has, where
/// at least one of them is not a *requirement*, is skipped in silence: it is a
/// well-formed edge that this view simply does not walk. Anything else — an
/// unresolved edge, or one naming an id the export does not carry — is a
/// `dangling-relation` gap.
fn selected_corpus_edges(
    export: &AssuranceExport,
    selection: &BTreeSet<RelationKind>,
    requirement_ids: &BTreeSet<ArtifactId>,
    all_ids: &BTreeSet<ArtifactId>,
    draft: &mut Draft,
) -> Vec<CorpusEdge> {
    let mut edges = Vec::new();
    for relation in &export.relations {
        let AssuranceRelation::Corpus {
            source,
            target,
            edge_type,
            resolution,
            ..
        } = relation
        else {
            continue;
        };
        let edge = CorpusEdge {
            source: ArtifactId::new(source.clone()),
            target: ArtifactId::new(target.clone()),
            edge_type: RelationKind::new(edge_type.clone()),
        };
        if !selection.contains(&edge.edge_type) {
            continue;
        }
        let resolved = *resolution == AssuranceResolution::Resolved;
        let both_requirements =
            requirement_ids.contains(&edge.source) && requirement_ids.contains(&edge.target);
        if resolved
            && all_ids.contains(&edge.source)
            && all_ids.contains(&edge.target)
            && !both_requirements
        {
            continue;
        }
        if resolved && both_requirements {
            edges.push(edge);
        } else {
            draft.gap(
                GraphGapKind::DanglingRelation,
                format!("{}:{}:{}", edge.source, edge.edge_type, edge.target),
                "selected relationship cannot resolve both accepted artifacts",
            );
        }
    }
    edges.sort_by(CorpusEdge::order);
    edges
}

/// Serialise a payload into a clean success.
fn ok<T: Serialize>(payload: &T) -> Result<Response, CoreError> {
    let value = serde_json::to_value(payload)
        .map_err(|e| CoreError::new(CoreErrorCode::Io, e.to_string()))?;
    Ok(Response::ok(value))
}

/// Validate the module-owned `AssuranceArgument` frontmatter contract.
///
/// # Errors
///
/// [`crate::ArgumentError`] for any of the seventeen predicates in the module
/// documentation. The message reproduces the retained implementation's;
/// the acceptance decision is what is contractual.
#[expect(
    clippy::too_many_lines,
    reason = "the retained parseAssuranceArgument is one function and splitting \
              it here would put the reading order somewhere other than the \
              order the oracle validates in, which is what a reader compares"
)]
pub fn parse_assurance_argument(value: &serde_json::Value) -> Checked<AssuranceArgument> {
    let object = record("argument", Some(value))?;
    for key in object.keys() {
        if !ALLOWED.contains(&key.as_str()) {
            return reject(format!("argument has unknown field {key}"));
        }
    }

    let id = string_at(object, "id")?;
    if !is_argument_id(&id) {
        return reject("argument id must match AA-<number>");
    }
    literal(
        object.get("type"),
        "type",
        &[("AssuranceArgument", ArgumentKind::AssuranceArgument)],
    )?;
    let status = literal(
        object.get("status"),
        "status",
        &[
            ("proposed", ArgumentStatus::Proposed),
            ("active", ArgumentStatus::Active),
            ("retired", ArgumentStatus::Retired),
        ],
    )?;
    let profile = string_at(object, "profile")?;
    if !profile.starts_with("ix://") {
        return reject("profile must be an ix:// reference");
    }

    let top = record("top_claim", object.get("top_claim"))?;
    exact_keys(
        top,
        "top_claim",
        &["id", "statement", "subject", "evidence_refs"],
        &["evidence_refs"],
    )?;
    // Optional (PLAT-965, PLAT-966): absent reads as empty so an argument
    // authored before the field existed still parses. The field is new, so
    // there is no retained null-tolerance to stay in parity with: an explicit
    // null is a wrong shape and `string_array` refuses it like any other.
    let top_evidence_refs = match top.get("evidence_refs") {
        None => Vec::new(),
        present => string_array("top_claim.evidence_refs", present, false)?,
    };

    let mut reasoning = Vec::new();
    for (index, item) in array_at(object, "reasoning")?.iter().enumerate() {
        let name = format!("reasoning[{index}]");
        let row = record(&name, Some(item))?;
        exact_keys(
            row,
            &name,
            &["id", "statement", "supports", "sufficiency_criteria"],
            &[],
        )?;
        reasoning.push(Reasoning {
            id: string_at(row, "id")?,
            statement: string_at(row, "statement")?,
            supports: string_at(row, "supports")?,
            sufficiency_criteria: string_array(
                &format!("{name}.sufficiency_criteria"),
                row.get("sufficiency_criteria"),
                true,
            )?,
        });
    }
    if reasoning.is_empty() {
        return reject("reasoning must not be empty");
    }

    let mut assumptions = Vec::new();
    for (index, item) in array_at(object, "assumptions")?.iter().enumerate() {
        let name = format!("assumptions[{index}]");
        let row = record(&name, Some(item))?;
        exact_keys(
            row,
            &name,
            &["id", "statement", "owner", "status", "review_by"],
            &[],
        )?;
        let review_by = string_at(row, "review_by")?;
        if !is_instant(&review_by) {
            return reject("review_by must be an ISO-8601 instant");
        }
        assumptions.push(Assumption {
            id: string_at(row, "id")?,
            statement: string_at(row, "statement")?,
            owner: string_at(row, "owner")?,
            status: literal(
                row.get("status"),
                "assumption status",
                &[
                    ("open", AssumptionStatus::Open),
                    ("accepted", AssumptionStatus::Accepted),
                    ("invalidated", AssumptionStatus::Invalidated),
                ],
            )?,
            review_by,
        });
    }

    let mut participants = Vec::new();
    for (index, item) in array_at(object, "participants")?.iter().enumerate() {
        let name = format!("participants[{index}]");
        let row = record(&name, Some(item))?;
        exact_keys(
            row,
            &name,
            &["id", "role", "authority", "independence"],
            &[],
        )?;
        participants.push(Participant {
            id: string_at(row, "id")?,
            role: string_at(row, "role")?,
            authority: string_at(row, "authority")?,
            independence: string_at(row, "independence")?,
        });
    }
    if participants.is_empty() {
        return reject("participants must not be empty");
    }

    let mut challenges = Vec::new();
    for (index, item) in array_at(object, "challenges")?.iter().enumerate() {
        let name = format!("challenges[{index}]");
        let row = record(&name, Some(item))?;
        exact_keys(
            row,
            &name,
            &[
                "id",
                "target",
                "statement",
                "status",
                "owner",
                "resolution_refs",
                "expires_at",
            ],
            &["resolution_refs", "expires_at"],
        )?;
        // `optionalStringAt` keys off PRESENCE, so an explicit null is a hard
        // error here...
        let expires_at = optional_string_at(row, "expires_at")?;
        if let Some(instant) = &expires_at
            && !is_instant(instant)
        {
            return reject("expires_at must be an ISO-8601 instant");
        }
        // ...while this one keys off TRUTHINESS, so an explicit null is
        // silently absent. The asymmetry is the retained implementation's and
        // is reproduced rather than tidied.
        let resolution_refs = match row.get("resolution_refs") {
            None | Some(serde_json::Value::Null) => None,
            Some(_) => Some(string_array(
                &format!("{name}.resolution_refs"),
                row.get("resolution_refs"),
                true,
            )?),
        };
        challenges.push(Challenge {
            id: string_at(row, "id")?,
            target: string_at(row, "target")?,
            statement: string_at(row, "statement")?,
            status: literal(
                row.get("status"),
                "challenge status",
                &[
                    ("open", ChallengeStatus::Open),
                    ("resolved", ChallengeStatus::Resolved),
                    ("accepted-risk", ChallengeStatus::AcceptedRisk),
                ],
            )?,
            owner: string_at(row, "owner")?,
            resolution_refs,
            expires_at,
        });
    }

    let mut relationships = Vec::new();
    for (index, item) in array_at(object, "relationships")?.iter().enumerate() {
        let name = format!("relationships[{index}]");
        let row = record(&name, Some(item))?;
        exact_keys(row, &name, &["target", "type"], &[])?;
        let target = string_at(row, "target")?;
        if !target.starts_with("ix://") {
            return reject(format!("{name}.target must be an ix:// reference"));
        }
        relationships.push(Relationship {
            target,
            kind: literal(
                row.get("type"),
                "relationship type",
                &[
                    ("supports", RelationshipType::Supports),
                    ("challenges", RelationshipType::Challenges),
                    ("references", RelationshipType::References),
                ],
            )?,
        });
    }

    unique_ids(
        "reasoning",
        &reasoning.iter().map(|r| r.id.as_str()).collect::<Vec<_>>(),
    )?;
    unique_ids(
        "assumptions",
        &assumptions
            .iter()
            .map(|a| a.id.as_str())
            .collect::<Vec<_>>(),
    )?;
    unique_ids(
        "participants",
        &participants
            .iter()
            .map(|p| p.id.as_str())
            .collect::<Vec<_>>(),
    )?;
    unique_ids(
        "challenges",
        &challenges.iter().map(|c| c.id.as_str()).collect::<Vec<_>>(),
    )?;

    let top_claim_id = string_at(top, "id")?;
    let mut node_ids: Vec<&str> = vec![top_claim_id.as_str()];
    node_ids.extend(reasoning.iter().map(|r| r.id.as_str()));
    node_ids.extend(assumptions.iter().map(|a| a.id.as_str()));
    {
        let mut seen: Vec<&str> = Vec::with_capacity(node_ids.len());
        for id in &node_ids {
            if seen.contains(id) {
                return reject("top claim, reasoning, and assumption ids must be unique");
            }
            seen.push(id);
        }
    }

    // Every chain of `supports` reaches the top claim. Cycle detection is per
    // START NODE, matching the retained `visited` set: a node reachable from
    // two starts is walked twice, which is correct — being visited on another
    // node's walk is not evidence that THIS node reaches the claim. Same
    // distinction FR-040 records for shared sub-claims (SR-007 FND-001).
    for start in &reasoning {
        let mut cursor = start;
        let mut visited: Vec<&str> = Vec::new();
        while cursor.supports != top_claim_id {
            if visited.contains(&cursor.id.as_str()) {
                return reject(format!(
                    "reasoning cycle does not reach top claim from {}",
                    start.id
                ));
            }
            visited.push(cursor.id.as_str());
            let Some(parent) = reasoning.iter().find(|r| r.id == cursor.supports) else {
                return reject(format!(
                    "reasoning {} supports unknown target {}",
                    start.id, cursor.supports
                ));
            };
            cursor = parent;
        }
    }

    for challenge in &challenges {
        if !node_ids.contains(&challenge.target.as_str()) {
            return reject(format!(
                "challenge {} targets unknown argument node {}",
                challenge.id, challenge.target
            ));
        }
    }

    Ok(AssuranceArgument {
        id,
        title: string_at(object, "title")?,
        kind: ArgumentKind::AssuranceArgument,
        status,
        owner: string_at(object, "owner")?,
        profile,
        top_claim: TopClaim {
            id: top_claim_id,
            statement: string_at(top, "statement")?,
            subject: string_at(top, "subject")?,
            evidence_refs: top_evidence_refs,
        },
        reasoning,
        assumptions,
        participants,
        challenges,
        relationships,
    })
}

/// Build one per-item retained observation for each of `items`, so
/// `quoin measurement verify`'s `constant-predictor` baseline arm
/// (`quoin_measurement::verify`) can recompute MP-222/PLAT-932's formula from
/// the stored collection rather than trusting an asserted number.
///
/// `metric` is the plan's own governed metric (the one the aggregate
/// proportion observation carries); the per-item observations are written
/// under `{metric}.constant-predictor-item`
/// (`quoin_measurement::constant_predictor_item_metric`), never under
/// `metric` itself, so they are never read as another slice of the governed
/// measurement.
///
/// # Errors
///
/// [`MeasurementErrorCode::CollectionInvalid`] when `plan_id`,
/// `definition_version` or `metric` is empty, or an item's `item_id`,
/// `family` or `expected` is empty — the identity and label fields this
/// baseline cannot be computed without — or two items share an `item_id`.
///
/// The checker also requires the item count to equal the governed aggregate
/// observation's own `population.examined`
/// (`constant_predictor_rows_mismatch` otherwise): pass every graded item the
/// aggregate rate was computed over, and no other.
pub fn item_observations(
    plan_id: &str,
    definition_version: &str,
    metric: &str,
    items: &[Item],
) -> Result<Vec<MeasurementObservation>, MeasurementError> {
    let plan_id = text(plan_id, "plan_id")?;
    let definition_version = text(definition_version, "definition_version")?;
    let item_metric_name = constant_predictor_item_metric(metric);
    let item_metric = text(&item_metric_name, "metric")?;
    let unit = text("fraction", "unit")?;

    let mut seen: BTreeSet<&str> = BTreeSet::new();
    items
        .iter()
        .map(|item| {
            if !seen.insert(item.item_id.as_str()) {
                return Err(MeasurementError::new(
                    MeasurementErrorCode::CollectionInvalid,
                    format!("duplicate `item_id` `{}`", item.item_id),
                ));
            }
            let mut dimensions: BTreeMap<String, JsonValue> = BTreeMap::new();
            dimensions.insert(
                dim::ITEM_ID.to_owned(),
                JsonValue::string(non_empty(&item.item_id, "item_id")?),
            );
            dimensions.insert(
                dim::FAMILY.to_owned(),
                JsonValue::string(non_empty(&item.family, "family")?),
            );
            dimensions.insert(
                dim::EXPECTED.to_owned(),
                JsonValue::string(non_empty(&item.expected, "expected")?),
            );
            dimensions.insert(
                dim::CONTESTED.to_owned(),
                JsonValue::Array(
                    item.contested
                        .iter()
                        .cloned()
                        .map(JsonValue::string)
                        .collect(),
                ),
            );
            dimensions.insert(
                dim::ACTUAL.to_owned(),
                JsonValue::string(item.actual.clone()),
            );
            // A tool that agreed with the primary reading or a contested
            // alternate scores `1.0`; MP-222's baseline formula never reads
            // this value back (it depends only on `expected`/`contested`),
            // but the field is not left `None` when the state is `Measured` —
            // the value is the observation's own per-item agreement, for
            // anything else that reads this collection later.
            let agreed = item.actual == item.expected || item.contested.contains(&item.actual);
            Ok(MeasurementObservation {
                metric: item_metric.clone(),
                plan_id: plan_id.clone(),
                definition_version: definition_version.clone(),
                state: MeasurementState::Measured,
                value: Some(f64::from(u8::from(agreed))),
                unit: unit.clone(),
                shape: MeasurementShape::Scalar,
                population: None,
                dimensions: Dimensions::stated(dimensions),
                reason: None,
            })
        })
        .collect()
}

fn receipt(arguments: &ArgMatches) -> Result<Response, String> {
    let decisions = bytes_of(&required(arguments, "decisions")?)?;
    let audits = arguments
        .get_one::<String>("audits")
        .map(|source| bytes_of(source))
        .transpose()?;
    let selections = arguments
        .get_many::<String>("select")
        .into_iter()
        .flatten()
        .map(|selection| parse_selection(selection))
        .collect::<Result<Vec<_>, _>>()?;
    let parents = arguments
        .get_many::<String>("parent")
        .into_iter()
        .flatten()
        .cloned()
        .collect::<Vec<_>>();
    let diff_paths: Option<Vec<String>> = arguments
        .get_many::<String>("diff-path")
        .map(|values| values.cloned().collect());
    let response = invoke(
        "change_assurance.receipt",
        &serde_json::json!({
            "repo": required(arguments, "repo")?,
            "record_digest": required(arguments, "record")?,
            "candidate_revision": required(arguments, "candidate-revision")?,
            "parent_digests": parents,
            "selections": selections,
            "decisions_hex": hex_of(&decisions),
            "audits_hex": audits.as_deref().map(hex_of),
            "diff_paths": diff_paths,
            "plan": arguments.get_one::<String>("plan"),
        }),
    )?;
    receipt_response(response, arguments.get_flag("json"), false)
}

