            .map(|cell| {
                cell.trim()
                    .trim_start_matches('`')
                    .trim_end_matches('`')
                    .trim()
                    .to_owned()
            })
            .collect();
        if cells.len() < 2 {
            continue;
        }
        let Some(first) = cells.first() else { continue };
        if !first.to_lowercase().contains(value.to_lowercase().as_str()) {
            continue;
        }
        for cell in cells.iter().skip(1) {
            if is_reason(cell) {
                return Some(cell.clone());
            }
        }
    }
    None
}

