    .expect("gitdir pointer");

    let mut log = IncidentLog::new();
    let env = FixedEnvironment::new()
        .with_var("XDG_CONFIG_HOME", root.path().join("xdg").to_string_lossy());
    let resolved = resolve_org(
        &worktree,
        &OrgOptions::default(),
        &env,
        &RuntimeContext::new(),
        &mut log,
    );
    let _ = resolved;
}

