        other.insert(
            "independence".to_owned(),
            serde_json::to_value(independence)
                .map_err(|error| AuditorError::report_not_serialisable(&error))?,
        );
    }

    Ok(AuditReport {
        findings,
        healthy,
        unevaluated,
        other,
    })
